e="number" min="0" step="0.0001" name="supplier_lines[<?php echo$i; ?>][unit_cost]"></td><td><input required type="number" min="0" max="100" step="0.001" name="supplier_lines[<?php echo$i; ?>][vat]" value="0"></td><td><input maxlength="64" name="supplier_lines[<?php echo$i; ?>][supplier_ref]"></td></tr><?php } ?></tbody></table></div><button class="button button-save">Create native supplier order</button></form><?php } ?>
