a['currency_code']); ?></option><?php } ?></select></label></div><label class="cpo-field"><span>Supplier payment reference</span><input required maxlength="255" name="supplier_payment_reference"></label><button class="button button-save"<?php echo empty($supplierState['banks'])?' disabled':''; ?>>Record native supplier payment</button></form><?php } ?>
